function resolveShortDuration(short, idx) {
    if (!short) return '1:24';
    const cur = (short.duration || '').trim();
    const isPlaceholder = !cur || ['0:58', '0:50', '0:15', '0:30', '0:45', '00:58', '00:15', '00:30'].includes(cur);
    if (!isPlaceholder) return cur;

    const vFile = (short.video || '').split('/').pop().split('?')[0];
    if (typeof KNOWN_VIDEO_DURATIONS !== 'undefined' && KNOWN_VIDEO_DURATIONS[vFile]) {
        return KNOWN_VIDEO_DURATIONS[vFile];
    }

    const idMap = {
        'short-1': '1:24',
        'short-2': '0:26',
        'short-3': '2:22',
        'short-4': '0:19',
        'short-5': '1:24',
        'short-6': '0:26'
    };
    if (idMap[short.id]) return idMap[short.id];

    const indexMap = ['1:24', '0:19', '2:22', '0:26', '1:24', '0:26'];
    return (idx !== undefined && indexMap[idx]) ? indexMap[idx] : (cur || '1:24');
}
window.resolveShortDuration = resolveShortDuration;

let inMemorySiteData = null;
window.inMemorySiteData = inMemorySiteData;

/**
 * Gets current site data from in-memory cache, localStorage, or initializes with default
 */
function getSiteData() {
    if (inMemorySiteData && typeof inMemorySiteData === 'object' && inMemorySiteData.projects) {
        return JSON.parse(JSON.stringify(inMemorySiteData));
    }

    try {
        const stored = localStorage.getItem(STORAGE_KEY);
        if (stored) {
            const parsed = JSON.parse(stored);

            // Auto-upgrade shorts with real video duration if they still hold placeholder values
            if (parsed.shorts && Array.isArray(parsed.shorts)) {
                let updatedDurations = false;
                parsed.shorts = parsed.shorts.map((s, idx) => {
                    const resolved = resolveShortDuration(s, idx);
                    if (s.duration !== resolved) {
                        s.duration = resolved;
                        updatedDurations = true;
                    }
                    return s;
                });
                if (updatedDurations) {
                    try {
                        localStorage.setItem(STORAGE_KEY, JSON.stringify(parsed));
                    } catch (e) {}
                }
            }

            const merged = {
                ...DEFAULT_SITE_DATA,
                ...parsed,
                navigation: { ...DEFAULT_SITE_DATA.navigation, ...(parsed.navigation || {}) },
                hero: { ...DEFAULT_SITE_DATA.hero, ...(parsed.hero || {}) },
                about: { ...DEFAULT_SITE_DATA.about, ...(parsed.about || {}) },
                showreel: { ...DEFAULT_SITE_DATA.showreel, ...(parsed.showreel || {}) },
                contact: { ...DEFAULT_SITE_DATA.contact, ...(parsed.contact || {}) },
                shortsHeader: { ...DEFAULT_SITE_DATA.shortsHeader, ...(parsed.shortsHeader || {}) },
                shorts: (parsed.shorts && parsed.shorts.length) ? parsed.shorts : DEFAULT_SITE_DATA.shorts
            };

            inMemorySiteData = merged;
            return merged;
        }
    } catch (e) {
        console.error("Error reading site data from localStorage", e);
    }

    const defaultClone = JSON.parse(JSON.stringify(DEFAULT_SITE_DATA));
    inMemorySiteData = defaultClone;
    return defaultClone;
}

/* ==========================================================================
   IndexedDB Media Storage Engine (Supports Large Direct Videos up to 1GB)
   ========================================================================== */
const MEDIA_DB_NAME = 'MahinPortfolioMediaDB';
const MEDIA_DB_VERSION = 1;
const MEDIA_STORE_NAME = 'mediaFiles';

function openMediaDB() {
    return new Promise((resolve, reject) => {
        if (!window.indexedDB) {
            return reject(new Error("IndexedDB not supported"));
        }
        const request = indexedDB.open(MEDIA_DB_NAME, MEDIA_DB_VERSION);
        request.onupgradeneeded = (e) => {
            const db = e.target.result;
            if (!db.objectStoreNames.contains(MEDIA_STORE_NAME)) {
                db.createObjectStore(MEDIA_STORE_NAME);
            }
        };
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
    });
}

async function saveMediaBlob(key, blob) {
    try {
        const db = await openMediaDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(MEDIA_STORE_NAME, 'readwrite');
            const store = tx.objectStore(MEDIA_STORE_NAME);
            store.put(blob, key);
            tx.oncomplete = () => resolve(true);
            tx.onerror = () => reject(tx.error);
        });
    } catch (err) {
        console.error("Error saving media to IndexedDB:", err);
        return false;
    }
}

async function getMediaBlob(key) {
    try {
        const db = await openMediaDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(MEDIA_STORE_NAME, 'readonly');
            const store = tx.objectStore(MEDIA_STORE_NAME);
            const request = store.get(key);
            request.onsuccess = () => resolve(request.result || null);
            request.onerror = () => reject(request.error);
        });
    } catch (err) {
        console.error("Error getting media from IndexedDB:", err);
        return null;
    }
}

async function removeMediaBlob(key) {
    try {
        const db = await openMediaDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(MEDIA_STORE_NAME, 'readwrite');
            const store = tx.objectStore(MEDIA_STORE_NAME);
            store.delete(key);
            tx.oncomplete = () => resolve(true);
            tx.onerror = () => reject(tx.error);
        });
    } catch (err) {
        console.error("Error removing media from IndexedDB:", err);
        return false;
    }
}

async function resolveMediaUrl(urlOrKey) {
    if (!urlOrKey) return '';
    if (typeof urlOrKey === 'string' && urlOrKey.startsWith('idb:')) {
        const key = urlOrKey.replace('idb:', '');
        try {
            const blob = await getMediaBlob(key);
            if (blob) {
                return URL.createObjectURL(blob);
            }
        } catch (e) {
            console.warn("Local media blob not found for key:", key);
        }
        // When accessed from another browser or device where local IndexedDB is not present,
        // return null so caller can safely fall back to bundled or YouTube video
        return null;
    }
    return urlOrKey;
}

window.openMediaDB = openMediaDB;
window.saveMediaBlob = saveMediaBlob;
window.getMediaBlob = getMediaBlob;
window.removeMediaBlob = removeMediaBlob;
window.resolveMediaUrl = resolveMediaUrl;


const CLOUD_DB_URL = '/api/syncData';

/**
 * Saves updated site data to localStorage & Live Cloud Backend
 */
async function saveSiteData(data) {
    inMemorySiteData = data;
    let localSaved = false;
    try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
        localSaved = true;
    } catch (e) {
        console.warn("localStorage quota exceeded. Storing in fallback and cloud.", e);
    }

    // Live Cloud Backend Realtime Sync across all devices worldwide
    let cloudSaved = false;
    try {
        const res = await fetch(CLOUD_DB_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(data)
        });
        if (res.ok) {
            cloudSaved = true;
            console.log("Live Cloud Backend synced successfully across all devices!");
        } else {
            console.warn("Cloud Backend returned status:", res.status);
        }
    } catch (err) {
        console.warn("Cloud Backend sync error:", err);
    }

    // If local storage failed due to large media, try to at least save in IndexedDB
    if (!localSaved && typeof saveMediaBlob === 'function') {
        try {
            const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
            await saveMediaBlob('siteData_fallback', blob);
        } catch (idbErr) {}
    }

    if (!localSaved && !cloudSaved) {
        if (typeof showToast === 'function') {
            showToast('Storage Limit Exceeded! Large video/image files cannot be stored. Please use YouTube/Cloud links.', 'error');
        }
        return false;
    }

    return true;
}

/**
 * Fetches latest site data from Live Cloud Backend and updates local storage (bypassing browser cache)
 */
function fetchCloudSiteData(callback) {
    try {
        const cacheBusterUrl = `${CLOUD_DB_URL}?t=${Date.now()}`;
        fetch(cacheBusterUrl, { cache: 'no-store' })
            .then(res => res.json())
            .then(cloudData => {
                if (cloudData && typeof cloudData === 'object' && Object.keys(cloudData).length > 0 && !cloudData.error) {
                    if (cloudData.shorts && Array.isArray(cloudData.shorts)) {
                        cloudData.shorts = cloudData.shorts.map((s, idx) => {
                            s.duration = resolveShortDuration(s, idx);
                            return s;
                        });
                    }
                    inMemorySiteData = cloudData;
                    try {
                        localStorage.setItem(STORAGE_KEY, JSON.stringify(cloudData));
                    } catch (e) {}
                    if (typeof callback === 'function') {
                        callback(cloudData);
                    }
                }
            })
            .catch(err => {
                console.warn("Using local cache, Cloud Backend offline:", err);
            });
    } catch (err) {
        console.warn("Cloud fetch error:", err);
    }
}

/**
 * Gets current admin password
 */
function getAdminPassword() {
    try {
        return localStorage.getItem(PASSWORD_STORAGE_KEY) || window._mem_admin_pass || DEFAULT_ADMIN_PASSWORD;
    } catch (e) {
        return window._mem_admin_pass || DEFAULT_ADMIN_PASSWORD;
    }
}

/**
 * Sets new admin password
 */
function setAdminPassword(newPassword) {
    if (newPassword && newPassword.trim().length >= 4) {
        const clean = newPassword.trim();
        try {
            localStorage.setItem(PASSWORD_STORAGE_KEY, clean);
        } catch (e) {}
        window._mem_admin_pass = clean;
        return true;
    }
    return false;
}

/**
 * Resets site data back to default
 */
function resetSiteDataToDefault() {
    localStorage.removeItem(STORAGE_KEY);
    return JSON.parse(JSON.stringify(DEFAULT_SITE_DATA));
}
